define(['jquery', 'core/str', 'core/config'], function ($, Str, mdlcfg) {var sync_content = {init: function (selector) {var context = $(selector);var synccontentStr;var syncingStr;var unknownerrorStr = '';$('#go1syncresult').hide();Str.get_strings([{key: 'synccontent',component: 'contentmarketplace_goone'},{key: 'syncing',component: 'contentmarketplace_goone'},{key: 'unknownerror',component: 'core'},]).done(function (strs) {synccontentStr = strs[0];syncingStr = strs[1];unknownerrorStr = strs[2];});var showResult = function (success, message) {context.prop('disabled', false);context.attr('value', synccontentStr);if (success) {$('#go1syncresult span').attr('data-flex-icon', 'core|notification-success');$('#go1syncresult .alert').removeClass('alert-danger').addClass('alert-success');$('#go1syncresult .flex-icon').removeClass('tfont-var-x-circle-fill').addClass('tfont-var-check-circle-fill');} else {$('#go1syncresult span').attr('data-flex-icon', 'core|notification-error');$('#go1syncresult .alert').removeClass('alert-success').addClass('alert-danger');$('#go1syncresult .flex-icon').removeClass('tfont-var-check-circle-fill').addClass('tfont-var-x-circle-fill');}$('#go1syncresult .alert-message').text(message || unknownerrorStr);$('#go1syncresult').show();};context.on('click', function (e) {e.preventDefault();context.prop('disabled', true);context.attr('value', syncingStr);$('#go1syncresult').hide();$('#go1syncresult .alert-message').text('');$.post({url: mdlcfg.wwwroot + "/totara/contentmarketplace/contentmarketplaces/goone/ajax/sync_content.php",data: {sesskey: mdlcfg.sesskey,}}).done(function (data) {showResult(Boolean(data && data.result), data && data.message);}).fail(function () {showResult(false, unknownerrorStr);});});}};return sync_content;});
